function wrap(
    bytes calldata name,
    address wrappedOwner,
    address resolver
) public override {
    (bytes32 labelhash, uint256 offset) = name.readLabel(0);
    bytes32 parentNode = name.namehash(offset);
    bytes32 node = _makeNode(parentNode, labelhash);

    if (parentNode == ETH_NODE) {
        revert IncompatibleParent();
    }

    address owner = ens.owner(node);

    if (
        owner != msg.sender &&
        !isApprovedForAll(owner, msg.sender) &&
        !ens.isApprovedForAll(owner, msg.sender)
    ) {
        revert Unauthorised(node, msg.sender);
    }

    if (resolver != address(0)) {
        ens.setResolver(node, resolver);
    }

    ens.setOwner(node, address(this));

    _wrap(node, name, wrappedOwner, 0, 0);
}

function unwrap(
    bytes32 parentNode,
    bytes32 labelhash,
    address newController
) public override onlyTokenOwner(_makeNode(parentNode, labelhash)) {
    if (parentNode == ETH_NODE) {
        revert IncompatibleParent();
    }
    _unwrap(_makeNode(parentNode, labelhash), newController);
}

function getFuses(bytes32 node)
    public
    view
    override
    returns (uint32 fuses, uint64 expiry)
{
    (, fuses, expiry) = getData(uint256(node));
    if (fuses == 0 && expiry == 0) {
        bytes memory name = names[node];
        if (name.length == 0) {
            revert NameNotFound();
        }
    }
}

function setSubnodeOwner(
    bytes32 parentNode,
    string calldata label,
    address newOwner,
    uint32 fuses,
    uint64 expiry
)
    public
    onlyTokenOwner(parentNode)
    canCallSetSubnodeOwner(parentNode, keccak256(bytes(label)))
    returns (bytes32 node)
{
    bytes32 labelhash = keccak256(bytes(label));
    node = _makeNode(parentNode, labelhash);
    (, , expiry) = _getDataAndNormaliseExpiry(parentNode, node, expiry);

    if (ens.owner(node) != address(this)) {
        ens.setSubnodeOwner(parentNode, labelhash, address(this));
        _addLabelAndWrap(parentNode, node, label, newOwner, fuses, expiry);
    } else {
        _transferAndBurnFuses(node, newOwner, fuses, expiry);
    }
}

function registerAndWrapETH2LD(
    string calldata label,
    address wrappedOwner,
    uint256 duration,
    address resolver,
    uint32 fuses,
    uint64 expiry
) external override onlyController returns (uint256 registrarExpiry) {
    uint256 tokenId = uint256(keccak256(bytes(label)));
    registrarExpiry = registrar.register(tokenId, address(this), duration);
    _wrapETH2LD(label, wrappedOwner, fuses, expiry, resolver);
}

function setSubnodeOwner(bytes32 node, bytes32 label, address owner) public virtual override authorised(node) returns(bytes32) {
    bytes32 subnode = keccak256(abi.encodePacked(node, label));
    _setOwner(subnode, owner);
    emit NewOwner(node, label, owner);
    return subnode;
}
